// components/Dashboard.js
import React, { useState, useEffect } from 'react';
import Sidebar from './Sidebar';
import Home from './pages/Home';
import LineRegistration from './pages/LineRegistration';
import TillRegistration from './pages/TillRegistration';
import Customer360 from './pages/Customer360';
import Activation from './pages/Activation';
import Transactions from './pages/Transactions';
import Report from './pages/Report';
import { USER_ROLES } from '../utils/api';
import Clock from './Clock';

const Dashboard = ({ currentUser, currentUserRole, currentPage, onNavigate, onLogout }) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [toast, setToast] = useState(null);

  const showToast = (message, isError = false) => {
    setToast({ message, isError });
    setTimeout(() => setToast(null), 3000);
  };

  const toggleMobileMenu = () => {
    setMobileMenuOpen(!mobileMenuOpen);
  };

  const closeMobileMenu = () => {
    setMobileMenuOpen(false);
  };

  const renderPage = () => {
    switch(currentPage) {
      case 'Home':
        return <Home showToast={showToast} currentUserRole={currentUserRole} />;
      case 'LineReg':
        return <LineRegistration showToast={showToast} />;
      case 'TillReg':
        return <TillRegistration showToast={showToast} />;
      case 'Customer360':
        return <Customer360 showToast={showToast} />;
      case 'Activation':
        return <Activation showToast={showToast} />;
      case 'Transactions':
        return <Transactions showToast={showToast} />;
      case 'Report':
        return <Report currentUserRole={currentUserRole} />;
      default:
        return <Home showToast={showToast} currentUserRole={currentUserRole} />;
    }
  };

  const hasActivationAccess = () => {
    return USER_ROLES[currentUserRole]?.canActivate !== false;
  };

  const getMenuPages = () => {
    const pages = ["Home", "Line Registration", "Till Registration", "Customer 360", "Report"];
    if (hasActivationAccess()) {
      pages.splice(4, 0, "Activation", "Transactions");
    }
    return pages;
  };

  const pageKeys = {
    "Home": "Home", 
    "Line Registration": "LineReg", 
    "Till Registration": "TillReg",
    "Activation": "Activation", 
    "Transactions": "Transactions",
    "Customer 360": "Customer360", 
    "Report": "Report"
  };

  const getIcon = (page) => {
    const icons = { 
      Home: "fa-home", 
      LineReg: "fa-user-plus", 
      TillReg: "fa-cash-register",
      Activation: "fa-toggle-on", 
      Transactions: "fa-exchange-alt",
      Customer360: "fa-id-card", 
      Report: "fa-chart-line" 
    };
    return icons[page] || "fa-circle";
  };

  useEffect(() => {
    if (mobileMenuOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => {
      document.body.style.overflow = '';
    };
  }, [mobileMenuOpen]);

  return (
    <div className="dashboard">
      <button className="mobile-menu-toggle" onClick={toggleMobileMenu}>
        <i className={`fas ${mobileMenuOpen ? 'fa-times' : 'fa-bars'}`}></i>
      </button>
      
      {mobileMenuOpen && (
        <div className="mobile-overlay" onClick={closeMobileMenu}></div>
      )}
      
      <Sidebar 
        currentPage={currentPage}
        currentUserRole={currentUserRole}
        onNavigate={onNavigate}
        onLogout={onLogout}
        menuPages={getMenuPages()}
        pageKeys={pageKeys}
        getIcon={getIcon}
        isOpen={mobileMenuOpen}
        onClose={closeMobileMenu}
      />
      
      <div className="main-content">
        <div className="card">
          {renderPage()}
        </div>
      </div>
      
      {toast && (
        <div className={`toast ${toast.isError ? 'toast-error' : ''}`}>
          <i className={`fas ${toast.isError ? 'fa-exclamation-circle' : 'fa-check-circle'}`}></i>
          {toast.message}
        </div>
      )}
      
      <Clock />
    </div>
  );
};

export default Dashboard;
